#' Evaluate log p(obs, z | theta) and log q(z | obs, theta) for augmented trees
#'
#' Given a list of augmented trees (produced by \code{\link{augment_trees}})
#' and a parameter vector, computes for each tree:
#' \itemize{
#'   \item \code{logf[i] = log p(obs, z_i | theta)} (model log-likelihood)
#'   \item \code{logg[i] = log q(z_i | obs, theta)} (proposal log-probability)
#' }
#' Both are evaluated at the supplied \code{pars}, regardless of which
#' parameters were used to simulate the trees.  This is essential for
#' shared-tree (Mode 2) evaluation where trees simulated at one particle
#' are scored at another.
#'
#' @param pars Numeric vector of 8 model parameters.
#' @param trees List of augmented-tree data frames (output of
#'   \code{\link{augment_trees}}).
#' @param model Integer vector \code{c(use_N, use_P, use_E)}.
#' @param link Link function: \code{0} = linear, \code{1} = exponential.
#' @return A named list:
#' \describe{
#'   \item{logf}{Numeric vector of \code{log p(obs, z_i | theta)}.}
#'   \item{logg}{Numeric vector of \code{log q(z_i | obs, theta)}.}
#' }
#' @keywords internal
eval_logf <- function(pars, trees, model = as.integer( c(0, 0, 0)), link = 0L, rho = 1.0) {
    .Call('_emphasis_eval_logf_cpp', PACKAGE = 'emphasis', pars, trees, model, link, rho)
}

#' The pendant PD and thinning rate the sampler sees at arbitrary times
#'
#' \code{Model::pendant_pd_at} reads P off the node that governs the segment a
#' candidate time falls in; \code{Model::nh_rate} is the intensity of the
#' sampler's birth process there.  This exposes both, so a test can hold P
#' against an independent recomputation from the augmented tree and against
#' \code{pd + n * (t - brts)} of the governing node, and can scan the intensity
#' over a segment to check that its value at the segment start dominates it.
#'
#' @param pars Numeric vector of 8 model parameters.
#' @param tree One augmented-tree data frame.
#' @param times Numeric vector of times at which to evaluate.
#' @param model Integer vector \code{c(use_N, use_M, use_D)}.
#' @param link Link function: 0 = linear, 1 = exponential, 2 = gaussian.
#' @param rho Sampling fraction.
#' @return A named list with \code{pd} (the pendant PD used) and \code{nh}
#'   (the non-homogeneous thinning rate) at each time.
#' @keywords internal
eval_nh_rate <- function(pars, tree, times, model = as.integer( c(0, 0, 0)), link = 0L, rho = 1.0) {
    .Call('_emphasis_eval_nh_rate_cpp', PACKAGE = 'emphasis', pars, tree, times, model, link, rho)
}

#' Draw augmented trees via importance sampling
#'
#' Augments an observed extant tree (given by its branching times) with
#' stochastically drawn extinct lineages, and returns the simulated trees
#' together with their log proposal probabilities.  Scoring (\code{logf})
#' and IS aggregation (\code{fhat}) are intentionally left to the R layer
#' via \code{\link{eval_logf}} and \code{.is_fhat}.
#'
#' @param brts Numeric vector of branching times (crown age first,
#'   sorted decreasing).
#' @param pars Numeric vector of 8 model parameters
#'   \code{c(beta_0, beta_N, beta_M, beta_D, gamma_0, gamma_N, gamma_M, gamma_D)}.
#' @param sample_size Number of valid augmented trees to collect.
#' @param maxN Maximum total augmentation attempts (including failures).
#' @param max_missing Maximum extinct lineages per augmented tree.
#' @param max_lambda Upper bound on the speciation rate (thinning bound).
#' @param num_threads Threads for parallel augmentation.
#' @param model Integer vector \code{c(use_N, use_P, use_E)}.
#' @param link Link function: \code{0} = linear, \code{1} = exponential.
#' @param rho Sampling fraction in \code{(0, 1]}.
#' @param parent_tip_start Tip start of the lineage that splits at each
#'   observed branching event, in the same forward-time order as \code{brts}
#'   (that is, \code{rev} of the decreasing \code{brts}); one entry per event,
#'   or one per node with the last ignored. Empty (the default) means the
#'   topology is not available: every observed lineage is then recorded as
#'   dating from the crown and every observed event gets \code{D = 0}, which
#'   is what a bare branching-time vector has always produced.
#' @return A named list:
#' \describe{
#'   \item{trees}{List of augmented-tree data frames.}
#'   \item{logf}{Per-tree log p(obs, z | theta).}
#'   \item{logg}{Per-tree log q(z | obs, theta).}
#'   \item{rejected}{Unhandled rejections.}
#'   \item{rejected_overruns}{Rejected: too many extinct lineages.}
#'   \item{rejected_lambda}{Rejected: lambda bound exceeded.}
#'   \item{rejected_zero_weights}{Rejected: zero IS weight (log weight -Inf).}
#'   \item{rejected_nonfinite}{Rejected: log weight +Inf or NaN.}
#'   \item{num_trees}{Number of trees returned (\code{length(trees)}).}
#'   \item{envelope_violations}{Thinning candidates drawn during this call
#'     whose acceptance probability exceeded 1, i.e. the envelope did not
#'     dominate the rate. Non-zero means the draws are not from the density
#'     \code{logg} charges them; a warning is issued.}
#'   \item{time}{Elapsed time (ms).}
#' }
#' @keywords internal
augment_trees <- function(brts, pars, sample_size, maxN, max_missing, max_lambda, num_threads, model = as.integer( c(0, 0, 0)), link = 0L, rho = 1.0, parent_tip_start = as.numeric( c())) {
    .Call('_emphasis_rcpp_mce', PACKAGE = 'emphasis', brts, pars, sample_size, maxN, max_missing, max_lambda, num_threads, model, link, rho, parent_tip_start)
}

#' Count thinning candidates with acceptance probability above 1
#'
#' The thinning sampler accepts a candidate speciation time with probability
#' \code{nh(t) / lambda_max}. A value above 1 means the envelope
#' \code{lambda_max} did not dominate the rate on that segment. The counter
#' accumulates over every augmentation call in the session.
#'
#' @param reset Logical; zero the counter after reading it.
#' @return Number of candidates with acceptance probability above 1 since the
#'   last reset.
#' @keywords internal
thinning_envelope_violations <- function(reset = FALSE) {
    .Call('_emphasis_rcpp_thinning_envelope_violations', PACKAGE = 'emphasis', reset)
}

#' function to perform one step of the E-M algorithm
#' @param brts vector of branching times
#' @param init_pars vector of initial parameter files
#' @param sample_size number of samples
#' @param maxN maximum number of failed trees
#' @param max_missing maximum number of species missing
#' @param max_lambda maximum speciation rate
#' @param lower_bound vector of lower bound values for optimization, should
#' be equal in length to the vector of init_pars
#' @param upper_bound vector of upper bound values for optimization, should
#' be equal in length to the vector of init_pars
#' @param xtol_rel relative tolerance for optimization
#' @param num_threads number of threads used.
#' @param copy_trees if set to true, the trees generated are returned as well
#' @param model integer vector of length 3: c(use_N, use_P, use_E)
#' @param link link function: 0 = linear (max(0,...)), 1 = exponential
#' @param rho sampling fraction in (0, 1]
#' @param parent_tip_start tip start of the lineage that splits at each
#' observed branching event, in the same forward-time order as \code{brts};
#' empty (the default) when only branching times are available, in which case
#' every observed lineage is recorded as dating from the crown and D = 0 at
#' every observed event.
#' @param rconditional R function that evaluates the GAM function.
#' @return a list with the following components:
#' \describe{
#'  \item{trees}{list of trees}
#'  \item{rejected}{number of rejected trees}
#'  \item{rejected_overruns}{number of trees rejected due to too large size}
#'  \item{rejected_lambda}{number of trees rejected due to lambda errors}
#'  \item{rejected_zero_weights}{number of trees rejected due to zero weight (log weight -Inf)}
#'  \item{rejected_nonfinite}{number of trees rejected due to a +Inf or NaN log weight}
#'  \item{num_trees}{number of trees the E-step returned}
#'  \item{estimates}{vector of estimates}
#'  \item{nlopt}{nlopt status}
#'  \item{fhat}{vector of fhat values}
#'  \item{time}{time elapsed}
#'  \item{weights}{vector of weights}
#'  \item{logf}{vector of log p(obs, z_i | theta) for each valid tree}
#'  \item{logg}{vector of log q(z_i | obs, theta) for each valid tree}
#' }
#' @keywords internal
em_cpp <- function(brts, init_pars, sample_size, maxN, max_missing, max_lambda, lower_bound, upper_bound, xtol_rel, num_threads, copy_trees, model = as.integer( c(0, 0, 0)), link = 0L, rho = 1.0, rconditional = NULL, parent_tip_start = as.numeric( c())) {
    .Call('_emphasis_rcpp_mcem', PACKAGE = 'emphasis', brts, init_pars, sample_size, maxN, max_missing, max_lambda, lower_bound, upper_bound, xtol_rel, num_threads, copy_trees, model, link, rho, rconditional, parent_tip_start)
}

